# Extract title and artist from each song line, search and match
playlist_id = create_result["playlist_id"]
for line in song_titles:
    # Split on " by " to get title and artist part
    if " by " in line:
        title_part, artist_part = line.split(" by ", 1)
    else:
        title_part = line
        artist_part = ""

    # Search for the song by title
    search_result = apis.spotify.search_songs(query=title_part, access_token=spotify_token)

    # Find the song that matches both title and artist
    matched_song = None
    if isinstance(search_result, list):
        for song in search_result:
            if song["title"].lower() == title_part.lower():
                # Check if artist matches
                song_artists = [a["name"].lower() for a in song["artists"]]
                # Check if any of the artists in the line match
                if artist_part:
                    # Split artist_part by comma for multiple artists
                    expected_artists = [a.strip().lower() for a in artist_part.split(",")]
                    if all(any(ea in sa for sa in song_artists) for ea in expected_artists):
                        matched_song = song
                        break
                else:
                    matched_song = song
                    break

    if matched_song:
        song_id = matched_song["song_id"]
        add_result = apis.spotify.add_song_to_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_token)
        print(f"Added '{line}' -> song_id {song_id}: {add_result}")
    else:
        print(f"No exact match found for '{line}'")

